<!DOCTYPE html><html lang="en" data-required-role="user" class="auth-pending"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>My Orders | TIO Perfume Collection</title><link rel="stylesheet" href="style.css?v=rebuilt2"><script src="tab-guard.js?v=rebuilt2"></script></head><body>
<header class="site-header"><a href="index.php" class="brand-logo"><span class="logo-mark"><img src="img/logo-header.png" alt="TIO Perfume Collection"></span></a><nav class="main-nav"><a href="index.php">HOME</a><a href="shop.php">SHOP</a><a href="best-sellers.php">BEST SELLERS</a><a href="orders.php" class="active">MY ORDERS</a><a href="contact.php">CONTACT</a></nav><div class="header-icons"><div class="auth-area" id="headerAuthArea"></div><a href="cart.php" class="icon-btn bag"><span>Bag</span><b id="cartCount">0</b></a></div></header>
<main><section class="page-hero"><h1>My Orders</h1><p class="breadcrumb">Track your perfume purchases and payment status.</p></section><section class="section"><div id="ordersWrap" class="orders-wrap"><p class="loading-note">Loading orders...</p></div></section></main>
<script src="script.js?v=rebuilt2"></script><script>
const pesos=n=>'₱'+Number(n||0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
async function loadOrders(){const d=await apiFetch('orders_api.php',{cache:'no-store'});if(!d.ok)return;const w=document.getElementById('ordersWrap');if(!d.orders.length){w.innerHTML='<div class="empty-state"><h2>No orders yet</h2><p>Your completed checkouts will appear here.</p><a href="shop.php" class="btn btn-primary">Shop Now</a></div>';return;}w.innerHTML=d.orders.map(o=>`<article class="order-card"><div class="order-card-head"><div><span class="order-number">Order #${o.id}</span><small>${escapeHtml(o.placed_at)}</small></div><div class="order-badges"><span>${escapeHtml(o.order_status)}</span><span>${escapeHtml(o.payment_status.replace('_',' '))}</span></div></div>${o.items.map(i=>`<div class="order-line"><span>${escapeHtml(i.product_name)} · ${escapeHtml(i.size_label)} × ${i.quantity}</span><strong>${pesos(i.line_total)}</strong></div>`).join('')}<div class="order-total"><span>${escapeHtml(o.payment_method.toUpperCase())}</span><strong>Total: ${pesos(o.total)}</strong></div></article>`).join('');}
document.addEventListener('tio-auth-ready',loadOrders);setTimeout(()=>{if(window.TIO_AUTH)loadOrders();},200);
</script></body></html>
